    step("读 /proc/self/ns/*:节点的 net=4026532605、pid=4026532603、ipc=4026532602、uts=4026532601。plain 的五个命名空间编号全都和节点不同;hostNetwork 的 hnet 与节点相同的是 net、uts;hostPID 的 hpid 与节点相同的是 pid;hostIPC 的 hipc 与节点相同的是 ipc。每个开关只打通对应的那个(mnt 始终是容器自己的)。", f=fl(F1, cur=[1, 2, 3], done=[0, 4]), t=tl(S(1), mark=lidx(S(1), 'hnet  ', 'hpid  ', 'hipc  '), done=lidx(S(1), 'plain  ')), kv=KV([['hostNetwork', '共享 net 和 uts(主机名也是节点的)'], ['hostPID', '共享 pid'], ['hostIPC', '共享 ipc;mnt 始终独立']], ['每个开关只打通一个'])),
    step("hostNetwork 下 Pod 的 IP 就是节点 IP(172.18.0.2),hostname 是节点名 kx-main-worker,ip link 能看到 15 个网卡(plain 里 11 个);netstat 能看到节点上 kubelet 监听的 10250、10248、10256;在里面再监听 10250 失败(Address already in use);plain 里监听 10250 不冲突。DNS:hnet 的 dnsPolicy 默认 ClusterFirst,在 hostNetwork 下实际退回节点的 DNS(nameserver 192.168.65.254),解析 kubernetes.default 超时;改成 dnsPolicy: ClusterFirstWithHostNet 后 nameserver 是 10.96.0.10,解析得到 10.96.0.1。", f=fl(F2, cur=[0, 1, 2], mark=[3]), t=tl(S(2), mark=lidx(S(2), 'hnet 的 IP', 'Address already in use', 'connection timed out'), done=lidx(S(2), 'ClusterFirstWithHostNet')), kv=KV([['IP 和端口', '与节点共用,会和节点上的服务冲突'], ['DNS', 'hostNetwork 要 ClusterFirstWithHostNet 才能解析集群内名字'], ['网络隔离', 'NetworkPolicy 对 hostNetwork Pod 通常无效(未验证)']], ['IP 和端口'])),
    step("hostPID:hpid 里 ps 有 34 行(plain 里 6 行),能看到节点上的 containerd 和 containerd-shim-runc-v2;PID 1 是 systemd(plain 的 PID 1 是 sleep)。hostIPC 与节点共享 ipc 命名空间(见第一节编号);共享后同一节点上的进程可以通过 SysV 共享内存、信号量、消息队列通信。", f=fl(F3, cur=[1, 2], done=[0, 3]), t=tl(S(3), mark=lidx(S(3), 'hpid 里 34', 'hpid 里 PID 1'), done=lidx(S(3), 'hpid 里能看到', 'hipc 与节点')), kv=KV([['hostPID', '能看到(和 root 时能杀掉)节点上所有进程'], ['hostIPC', '共享 SysV IPC,跨容器泄露共享内存风险'], ['典型用途', '监控代理、调试工具']], ['hostPID'])),
